const raw = $input.first().json;
const grants = Array.isArray(raw) ? raw : [raw];
const runDate = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

const closingSoon = grants.filter(g => g.closingSoon === true);
const newGrants = grants.filter(g => g.isNewMatch === true && !g.closingSoon);
const allNew = [...closingSoon, ...newGrants];

if (allNew.length === 0) {
  return [{ json: { skip: true } }];
}

const formatValue = (g) => {
  if (g.minAward && g.maxAward) return `£${Number(g.minAward).toLocaleString('en-GB')} – £${Number(g.maxAward).toLocaleString('en-GB')}`;
  if (g.minAward) return `From £${Number(g.minAward).toLocaleString('en-GB')}`;
  return 'TBC';
};

const buildGrantRow = (g, rowStyle) => `<tr style='${rowStyle}'>
  <td>${(g.title || g.contractTitle || 'N/A').slice(0, 80)}</td>
  <td>${g.fundingBody || g.portal || 'N/A'}</td>
  <td>${formatValue(g)}</td>
  <td><strong>${g.submissionDeadline || g.closingDate || 'TBC'}</strong>${g.daysUntilClose ? ` (${g.daysUntilClose}d)` : ''}</td>
  <td>${g.matchedKeyword || ''}</td>
  <td><a href='${g.noticeUrl || g.applicationUrl || g.url || '#'}'>Apply</a></td>
</tr>`;

const tableHead = `<tr style='background:#333;color:#fff;'><th>Grant / Competition</th><th>Funding Body</th><th>Award Range</th><th>Deadline</th><th>Matched Keyword</th><th>Link</th></tr>`;

const closingSoonSection = closingSoon.length > 0 ? `
<h3 style='color:#c00;'>⚠️ Closing Soon — Act This Week (${closingSoon.length})</h3>
<p>These competitions close within 21 days. Application preparation should begin immediately.</p>
<table border='1' cellpadding='6' style='width:100%;border-collapse:collapse;font-size:13px;'>
${tableHead}
${closingSoon.map(g => buildGrantRow(g, 'background:#fff5f5;')).join('')}
</table>` : '';

const newSection = newGrants.length > 0 ? `
<h3>🆕 New Opportunities (${newGrants.length})</h3>
<table border='1' cellpadding='6' style='width:100%;border-collapse:collapse;font-size:13px;'>
${tableHead}
${newGrants.map(g => buildGrantRow(g, '')).join('')}
</table>` : '';

const html = `<!DOCTYPE html><html><body style='font-family:Arial,sans-serif;max-width:750px;margin:0 auto;padding:20px;'>
<h2>🏆 Grant Intelligence — ${runDate}</h2>
<p>${allNew.length} relevant competition(s) found · ${closingSoon.length} closing within 21 days</p>
<hr/>
${closingSoonSection}
${newSection}
<hr/>
<p style='color:#666;font-size:12px;'><strong>Sources monitored:</strong> Innovate UK Funding Service · UKRI Gateway · EC Horizon Europe (SEDIA)</p>
<p style='color:#999;font-size:11px;'>Source: conceivable_extension/uk-grant-alerts</p>
</body></html>`;

const subject = closingSoon.length > 0
  ? `🔴 Grant Alert: ${closingSoon.length} competition(s) closing soon — ${runDate}`
  : `📋 Grant Intelligence: ${newGrants.length} new competition(s) found — ${runDate}`;

return [{ json: { html, subject, skip: false, grantCount: allNew.length } }];
